// ============================================================================
// RFP - Chat: Check message. The Teams bot (services/teams-bot) POSTs one user message or one card button:
//   {text, action: {name, tender_id, reason} | null, user: {id, name}, locale, conversation: {id, type}, can_act}
// can_act is the bot's decision (the user is in TEAMS_APPROVER_USERS, or no approver list is set): the webhook key proves
// the bot sent it. Three routes, decided by code:
//   tool  = a card button or a fixed command (help is answered here; "tenders", "status"): one tool, no LLM
//   agent = any other question: the chat agent and its tools
//   reply = an empty, too long or invalid message: answered here
// ============================================================================
const CHAT_LLM_PROVIDER = 'ollama';      // patched by n8n/init/init.js (CHAT_LLM_PROVIDER, else DECK_LLM_PROVIDER, else LLM_PROVIDER)
const MAX_CHARS = 1000;                   // a Teams message longer than this is refused, not cut (a cut question is another question)

const raw = $input.first().json.body;
let req = raw;
if (typeof raw === 'string') { try { req = JSON.parse(raw); } catch (e) { req = null; } }
if (!req || typeof req !== 'object' || Array.isArray(req)) req = {};
const s = v => (v == null ? '' : String(v));
// control and invisible characters out (a pasted message can carry them), spaces folded
const clean = v => s(v).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F\u200B-\u200F\u202A-\u202E\u2060-\u2064\uFEFF]/g, '').replace(/[ \t]+/g, ' ').trim();

const text = clean(req.text);
const user = { id: clean(req.user && req.user.id).slice(0, 80), name: clean(req.user && req.user.name).slice(0, 80) };
const conversationId = clean(req.conversation && req.conversation.id).slice(0, 200) || `user:${user.id || 'unknown'}`;
const canAct = req.can_act === true;
const locale = clean(req.locale).toLowerCase();

// the answer's language: a vote of the message's French and English words (an accent counts for French), the Teams locale on
// a tie ("Power BI ?"). Only words of one language: "details" is English, "détails" French
const FR = /(?<![\p{L}'])(le|la|les|des|du|de|une?|est|sont|pour|quels?|quelles?|qui|quoi|avons|nous|appels?|offres?|marches|bonjour|merci|equipe|couvrons|statut|diapo|lacunes?|acheteur|aide|cette|semaine|montre|donne)(?![\p{L}'])/giu;
const EN = /(?<![\p{L}'])(the|which|what|who|do|does|we|our|have|has|tenders?|details?|status|show|list|generate|deck|slide|cover|gaps?|buyer|team|budget|help|top|of|for|is|are|me|my|this|week|please)(?![\p{L}'])/giu;
const votes = re => (text.match(re) || []).length;
const fr = votes(FR) + (/[éèêàâùûçôî]/i.test(text) ? 1 : 0), en = votes(EN);
const language = fr > en ? 'fr' : en > fr ? 'en' : locale.startsWith('fr') ? 'fr' : 'en';
const meta = { conversation_id: conversationId, conversation_type: clean(req.conversation && req.conversation.type) || 'personal', user, language, can_act: canAct, provider: CHAT_LLM_PROVIDER };
const reply = t => [{ json: { _route: 'reply', ...meta, reply: { text: t, language, cards: [] } } }];
const tool = (name, fields = {}) => [{ json: { _route: 'tool', ...meta, tool: name, can_act: canAct ? 'yes' : 'no', ...fields } }];
const L = (en, fr) => (language === 'fr' ? fr : en);

// ---- a card button (Action.Submit): the bot sends its data as action
const action = req.action && typeof req.action === 'object' ? req.action : null;
if (action) {
  const name = clean(action.name), id = clean(action.tender_id).slice(0, 80);
  const BUTTONS = { generate_deck: 'start_deck', no_bid: 'record_no_bid', deck_status: 'deck_status', matrix: 'get_requirements_matrix', tender: 'get_tender' };
  if (!BUTTONS[name]) return reply(L('This button is not known to the assistant.', 'Ce bouton est inconnu de l\'assistant.'));
  if (!id) return reply(L('This button has no tender id.', 'Ce bouton n\'a pas d\'identifiant d\'appel d\'offres.'));
  if (name === 'no_bid' && clean(action.reason).length < 3) return reply(L('A no-bid needs a reason (3 characters or more): write it in the card, then press No-bid again.',
    'Un no-bid demande une raison (3 caractères ou plus) : écrivez-la dans la carte, puis appuyez de nouveau sur No-bid.'));
  return tool(BUTTONS[name], { tender_id: id, reason: clean(action.reason).slice(0, 300) });
}

// ---- a typed message
if (!text) return reply(L('Send me a question about the tenders, for example "top tenders" or "details of [tender id]". Type "help" for more.',
  'Posez-moi une question sur les appels d\'offres, par exemple « top appels d\'offres » ou « détails de [id] ». Tapez « aide » pour plus.'));
if (text.length > MAX_CHARS) return reply(L(`Your message is too long (${text.length} characters, at most ${MAX_CHARS}). Ask a shorter question.`,
  `Votre message est trop long (${text.length} caractères, ${MAX_CHARS} au plus). Posez une question plus courte.`));

const cmd = text.toLowerCase().replace(/[!?.]+$/, '').trim();
if (/^(help|aide|\?|commands?|commandes?)$/.test(cmd)) {
  return reply(L(
    'I answer from the tender store and the knowledge base, and I can act on decks:\n' +
    '- "top tenders", "which tenders fit this week", "details of [id]"\n' +
    '- "requirements matrix of [id]", "gaps of [id]", "team for [id]", "who is the buyer of [id]", "budget range of [id]"\n' +
    '- "do we cover Power BI and 2 data engineers", "who has a PMP"\n' +
    '- "generate the deck for [id]", "status", "refine slide 5 of deck [deck id]: make it shorter", "export [id]"\n' +
    (canAct ? 'You can run the actions (deck, refine, no-bid).' : 'Actions (deck, refine, no-bid) are for the approvers only: you can ask questions.'),
    'Je réponds à partir des appels d\'offres analysés et de la base de connaissances, et j\'agis sur les présentations :\n' +
    '- « top appels d\'offres », « quels appels d\'offres cette semaine », « détails de [id] »\n' +
    '- « matrice des exigences de [id] », « lacunes de [id] », « équipe pour [id] », « qui est l\'acheteur de [id] », « fourchette de budget de [id] »\n' +
    '- « couvrons-nous Power BI et 2 data engineers », « qui a une certification PMP »\n' +
    '- « génère la présentation de [id] », « statut », « affine la diapo 5 du deck [id deck] : plus courte », « exporter [id] »\n' +
    (canAct ? 'Vous pouvez lancer les actions (présentation, affinage, no-bid).' : 'Les actions (présentation, affinage, no-bid) sont réservées aux approbateurs : vous pouvez poser des questions.')));
}
if (/^(tenders|top( \d+)?( tenders)?|top tenders|appels d'offres|top appels d'offres|offres)$/.test(cmd)) return tool('list_tenders', { limit: '5' });
if (/^(status|statut)$/.test(cmd)) return tool('deck_status', { tender_id: '' });

// ---- the agent: the message and what code knows (never a fact the model could get wrong)
const today = (() => { try { return $now.toFormat('yyyy-MM-dd'); } catch (e) { return new Date().toISOString().slice(0, 10); } })();
const prompt = `LANGUAGE: ${language === 'fr' ? 'French' : 'English'}\nTODAY: ${today}\nUSER MAY RUN ACTIONS: ${canAct ? 'yes' : 'no'}\n` +
  `USER: ${user.name || 'unknown'}\nMESSAGE: ${text}`;
return [{ json: { _route: 'agent', ...meta, text, prompt } }];

// ============================================================================
// RFP - Chat: Check answer. The chat agent's answer -> the bot's reply {text, language, cards, audit}. Code, not the model,
// decides what reaches Teams:
//   - the cards come from the tools' results (chatCards), never from the model's text;
//   - a line of the model's text that names a tender id or a knowledge-base document (CV, project, stack) no tool returned, or a
//     number found neither in a tool result nor in the user's message, is removed (an invented fact never reaches the user); if
//     nothing is left, a fixed sentence introduces the cards;
//   - a model error (429 quota, timeout, invalid answer) gives a short, honest message, never the raw error;
//   - a deck started by start_deck is handed to "Watch deck" (after Respond) so the bot posts it when it is ready.
// ============================================================================
// ---- shared helpers ----
// the Teams bot's cards (RFP - Chat): built by code from the tools' results, never written by a model. One card per kind (the
// last call wins), at most 2 per answer. Their shapes are rendered by services/teams-bot/bot/cards.py
const chatCards = results => {
  const kinds = new Map();
  for (const d of results) {
    if (!d || d.ok !== true) continue;
    const t = d.tender || {};
    let c = null;
    if (d.tool === 'list_tenders') c = { type: 'tender_list', data: { tenders: d.tenders || [], total: d.total || 0, filters: d.filters || [] } };
    else if (d.tool === 'get_tender' || d.tool === 'record_no_bid') c = { type: 'tender', data: t };
    else if (d.tool === 'get_requirements_matrix') c = { type: 'matrix', data: { tender: t, rows: (d.rows || []).slice(0, 8), total: d.total || 0 } };
    else if (d.tool === 'search_knowledge') c = { type: 'coverage', data: { rows: (d.rows || []).slice(0, 8), team: d.team || [] } };
    else if (d.tool === 'deck_status' && d.last_run) c = { type: 'deck', data: { ...d.last_run, title: t.title || null, tender_id: t.tender_id || d.last_run.tender_id } };
    else if (d.tool === 'deck_status' && Array.isArray(d.runs) && d.runs.length) c = { type: 'deck', data: d.runs[0] };
    else if (d.tool === 'export_deck') c = { type: 'deck', data: { status: 'done', deck_id: d.deck_id, deck_url: d.deck_url, placeholders: d.placeholders, title: t.title, tender_id: t.tender_id } };
    else if (d.tool === 'start_deck') c = { type: 'deck', data: { status: 'running', run_id: d.run_id, title: t.title, tender_id: t.tender_id } };
    if (c) { kinds.delete(c.type); kinds.set(c.type, c); }
  }
  return [...kinds.values()].slice(-2);
};
// ---- end helpers ----
const MAX_LINES = 8, MAX_CHARS = 1200;
const msg = $('Check message').first().json;
const r = $input.first().json || {};
const fr = msg.language === 'fr';
const L = (en, f) => (fr ? f : en);

// ---- the tools' results: each observation is the JSON of the tool's output item(s)
const parse = v => {
  if (v && typeof v === 'object') return v;
  try { return JSON.parse(String(v)); } catch (e) { return null; }
};
const resultOf = obs => {
  let j = parse(obs);
  if (Array.isArray(j)) j = j[0];
  if (j && typeof j === 'object' && typeof j.response === 'string') j = parse(j.response);   // some n8n versions wrap the item
  return j && typeof j === 'object' && typeof j.tool === 'string' ? j : null;
};
const results = (r.intermediateSteps || []).map(st => resultOf(st.observation)).filter(Boolean);
const facts = JSON.stringify(results) + ' ' + String(msg.text || '');

// ---- what the model may say: ids and numbers that a tool returned (or the user wrote)
const ids = new Set();
const collect = o => { if (Array.isArray(o)) o.forEach(collect); else if (o && typeof o === 'object') for (const [k, v] of Object.entries(o)) { if (/(^|_)id$/.test(k) && typeof v === 'string') ids.add(v); collect(v); } };
collect(results);
const digitRuns = new Set((facts.match(/\d+/g) || []).map(x => x.replace(/^0+(?=\d)/, '')));
const factNumbers = new Set((facts.replace(/(\d)[\s\u00A0\u202F](?=\d{3}\b)/g, '$1').match(/\d+(?:[.,]\d+)?/g) || []).map(x => String(Number(x.replace(',', '.')))));
// a number of 2 digits or more, or any number with %, € or a million / thousand unit, must be a fact
const NUM = /(\d[\d\s\u00A0\u202F]*\d|\d)(?:[.,](\d+))?\s*(%|€|eur\b|euros?\b|k€|m€|k\b|m\b|millions?\b|thousand\b|milliers?\b)?/gi;
const numberOk = (m, intPart, frac, unit) => {
  const int = intPart.replace(/[\s\u00A0\u202F]/g, '');
  if (int.length < 2 && !unit) return true;                                  // "slide 5", "3 tenders": too common to be a claim
  const value = Number(int + (frac ? '.' + frac : ''));
  const u = (unit || '').toLowerCase();
  const scaled = /^(m€|m|millions?)$/.test(u) ? value * 1e6 : /^(k€|k|thousand|milliers?)$/.test(u) ? value * 1e3 : value;
  return factNumbers.has(String(scaled)) || factNumbers.has(String(value)) || digitRuns.has(int.replace(/^0+(?=\d)/, ''));
};
// tender ids ('T' + a base-36 hash: T1teiowa, Tdoatt8; one digit at least, so "Tenders" is a word), deck and run ids (hex with a letter)
const ID_LIKE = /\b(T(?=[a-z]*\d)[0-9a-z]{6,8}|(?=\d*[a-f])[a-f0-9]{8}|(?=\d*[a-f])[a-f0-9]{12})\b/g;
// knowledge-base documents as the RAG names them (CV_13_Isabella_Ross.pdf, olivesoft_Project_..., demo_...): a small model
// writes a plausible name with the wrong number ("CV_17_Nora_Ellis.pdf"), so the exact name must be in a tool result
const DOC_LIKE = /\b((?:CV_)?\d{1,3}_[A-Z][A-Za-z]*_[A-Za-z_]+\.pdf|(?:olivesoft|demo)_[A-Za-z0-9_]+)\b/g;
const lineOk = line => {
  for (const m of line.matchAll(ID_LIKE)) if (!ids.has(m[1]) && !String(msg.text || '').includes(m[1])) return false;
  for (const m of line.matchAll(DOC_LIKE)) if (!facts.includes(m[1])) return false;
  for (const m of line.matchAll(NUM)) if (!numberOk(m[0], m[1], m[2], m[3])) return false;
  return true;
};

const say = (text, extra = {}) => [{ json: { reply: { text, language: msg.language, cards: chatCards(results), ...extra }, watch: null } }];

// ---- the model failed: an honest message (the raw error stays in the n8n execution)
if (r.error || typeof r.output !== 'string') {
  const e = String((r.error && (r.error.message || r.error.description)) || r.error || '');
  // busy: the bot says so, waits and asks once more by itself (services/teams-bot, core.py)
  if (/429|rate.?limit|quota|too many requests/i.test(e)) return say(L('The assistant is busy (the model\'s rate limit). Wait a minute and ask again.',
    'L\'assistant est occupé (limite de débit du modèle). Attendez une minute et reposez la question.'), { busy: true });
  if (/timeout|timed out|ETIMEDOUT|ECONNREFUSED|ENOTFOUND|fetch failed/i.test(e)) return say(L('The assistant\'s model did not answer in time. Try again in a moment.',
    'Le modèle de l\'assistant n\'a pas répondu à temps. Réessayez dans un instant.'));
  return say(L('The assistant could not answer this question. Try again, or ask it differently.', 'L\'assistant n\'a pas pu répondre. Réessayez ou reformulez.'));
}

// ---- the model's text, checked line by line
const lines = r.output.replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/\r/g, '').split('\n')
  .map(l => l.replace(/^#+\s*/, '').replace(/\*\*/g, '').trimEnd()).filter(l => l.trim() && !/^\s*\|?[-:| ]+\|?\s*$/.test(l));
const kept = lines.filter(lineOk);
const removed = lines.length - kept.length;
let text = kept.slice(0, MAX_LINES).join('\n');
if (text.length > MAX_CHARS) text = text.slice(0, MAX_CHARS - 1) + '…';
const cards = chatCards(results);
if (!text) text = cards.length ? L('Here is what the tools returned:', 'Voici ce que les outils ont renvoyé :')
  : L('I could not find a reliable answer to this question.', 'Je n\'ai pas trouvé de réponse fiable à cette question.');
if (removed) text += '\n' + L(`(${removed} line${removed > 1 ? 's' : ''} removed: not supported by the data.)`, `(${removed} ligne${removed > 1 ? 's' : ''} retirée${removed > 1 ? 's' : ''} : non étayée${removed > 1 ? 's' : ''} par les données.)`);

const audit = results.filter(d => d.ok && d.audit).map(d => d.audit);
const started = results.find(d => d.tool === 'start_deck' && d.ok && d.run_id);
return [{ json: {
  reply: { text, language: msg.language, cards, audit },
  watch: started ? { run_id: started.run_id, tender_id: started.tender.tender_id, title: started.tender.title } : null,
  checks: { tools: results.map(d => `${d.tool}:${d.ok ? 'ok' : 'failed'}`), removed_lines: removed },
} }];

// ============================================================================
// RFP - Chat Tools: the tools of the Teams chat agent (RFP - Chat) and of the bot's buttons. One item in ({tool, ...inputs},
// from the agent's tool nodes, or "Run command" of RFP - Chat: the same code); one item out: {ok, tool, ...facts}, the JSON
// the agent reads and Check answer builds the cards from. Every fact comes from the RAG service (tender store, requirements matrix,
// team, gaps, /retrieve) or the proposal studio (buyer research, market study, decks); nothing here is written by a model.
// The actions (start_deck, refine_slide, record_no_bid) run only when can_act is 'yes': set by code in RFP - Chat from
// TEAMS_APPROVER_USERS (the bot), never by the model. Tender text is data: it is cut and passed on, never followed.
// ============================================================================
// where the services are, as seen from inside n8n (patched by n8n/init/init.js for the compose network)
const RAG_URL = 'http://host.docker.internal:8001';
const STUDIO_URL = 'http://host.docker.internal:8091';
const REFINE_URL = 'http://127.0.0.1:5678/webhook/cstam/refine-slide';   // "RFP - Refine Slide", same n8n (not localhost: IPv6 first)
const WEB_APP_URL = 'http://localhost:5173';                              // the links the Teams user opens (TEAMS_WEB_APP_URL)

const inp = $input.first().json || {};
const s = v => (v == null ? '' : String(v)).replace(/\s+/g, ' ').trim();
const cut = (v, n) => { const t = s(v); return t.length > n ? t.slice(0, n - 1) + '…' : t; };
const tool = s(inp.tool);
const canAct = s(inp.can_act) === 'yes';
const out = data => [{ json: data }];
const fail = (error, extra = {}) => out({ ok: false, tool, error, ...extra });

// the studio's id of a tender (its tender_store.safe_id), as the web app sends it
const studioId = id => s(id).replace(/[^A-Za-z0-9_-]/g, '-').slice(0, 64).replace(/^-+|-+$/g, '');
const tenderLink = id => `${WEB_APP_URL}/tenders/${encodeURIComponent(id)}`;
const deckLink = (deckId, tenderId) => `${WEB_APP_URL}/decks/${encodeURIComponent(deckId)}${tenderId ? `?tender=${encodeURIComponent(tenderId)}` : ''}`;
// an id the model typed: quotes, backticks and a trailing dot removed ("`T1w50xyr`." -> T1w50xyr)
const cleanRef = v => s(v).replace(/^[\s"'`«“]+|[\s"'`»”.,;:!?]+$/g, '');

const http = async (method, url, body) => {
  try {
    const r = await this.helpers.httpRequest({ method, url, json: true, timeout: 30000, returnFullResponse: true, ignoreHttpStatusErrors: true,
      ...(body === undefined ? {} : { body, headers: { 'Content-Type': 'application/json' } }) });
    let b = r.body;
    if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { /* not JSON */ } }
    return { status: Number(r.statusCode) || 0, body: b };
  } catch (e) {
    return { status: 0, body: null, error: s(e.message || e).slice(0, 160) };
  }
};

// ---- today, in n8n's timezone (as Main's Config): days_left counts from it
const TZ = (typeof $now !== 'undefined' && $now && $now.zoneName) || 'UTC';
const today = (() => { try { const p = Object.fromEntries(new Intl.DateTimeFormat('en-US', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' })
  .formatToParts(new Date()).map(x => [x.type, x.value])); return `${p.year}-${p.month}-${p.day}`; } catch (e) { return new Date().toISOString().slice(0, 10); } })();
const daysBetween = (a, b) => Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);
const isoDay = v => (/^\d{4}-\d{2}-\d{2}/.test(s(v)) ? s(v).slice(0, 10) : '');

// ---- the RAG's tender store
let store = null;
const tenders = async () => {
  if (store) return store;
  const r = await http('GET', `${RAG_URL}/api/tenders`);
  if (r.status !== 200 || !r.body || !Array.isArray(r.body.tenders)) {
    store = { error: r.status ? `the RAG service answered HTTP ${r.status}` : 'the RAG service is not reachable' };
    return store;
  }
  store = { list: r.body.tenders };
  return store;
};
const isDemo = t => t.data_mode === 'demo' || s(t.source).toLowerCase() === 'demo';
const counts = t => {
  const m = (t.rag_analysis && t.rag_analysis.requirements_matrix) || [];
  const c = st => m.filter(r => r.status === st).length;
  return { requirements: m.length, covered: c('covered'), partial: c('partial'), missing: c('missing'),
    mandatory_missing: m.filter(r => r.status === 'missing' && r.mandatory).length };
};
// the compact facts of one stored tender: what the agent reads and what the bot's TenderCard shows
const summary = t => {
  const fit = t.rag_analysis && t.rag_analysis.fit_score ? t.rag_analysis.fit_score.overall : null;
  const deadline = isoDay(t.deadline);
  return {
    tender_id: t.tender_id, title: cut(t.title, 140), buyer: cut(t.client, 80), demo: isDemo(t), source: s(t.source),
    published: isoDay(t.published), deadline: deadline || null, days_left: deadline ? daysBetween(today, deadline) : null,
    budget: s(t.estimated_budget) || null, language: s(t.language) || null, country: s(t.country) || null,
    fit: typeof fit === 'number' ? fit : null, ...counts(t),
    decision: t.decision ? { decision: t.decision.decision, reason: cut(t.decision.reason, 120) || null } : null,
    url: tenderLink(t.tender_id), notice_url: s(t.source_url) || null,
  };
};
// a tender by id, else by words of its title or buyer ("the Lille tender"): one match is used, several are listed
const findTender = async ref => {
  const st = await tenders();
  if (st.error) return { error: st.error };
  const id = cleanRef(ref);
  if (!id) return { error: 'no tender id given' };
  const exact = st.list.find(t => t.tender_id === id) || st.list.find(t => s(t.tender_id).toLowerCase() === id.toLowerCase());
  if (exact) return { tender: exact };
  const fold = x => s(x).toLowerCase().normalize('NFD').replace(/[\u0300-\u036F]/g, '');
  const words = fold(id).split(/[^a-z0-9]+/).filter(w => w.length > 2);
  const hits = words.length ? st.list.filter(t => words.every(w => fold(`${t.title} ${t.client}`).includes(w))) : [];
  if (hits.length === 1) return { tender: hits[0] };
  if (hits.length > 1) return { error: `several tenders match "${cut(id, 60)}"`, candidates: hits.slice(0, 5).map(summary) };
  return { error: `no tender with id or words "${cut(id, 60)}" in the tender store` };
};
const notFound = f => fail(f.error, f.candidates ? { candidates: f.candidates } : { hint: 'call list_tenders to see the ids' });
const needAct = () => fail('not allowed: only the approvers listed in TEAMS_APPROVER_USERS can run this action', { not_allowed: true });

// ---- the studio's copy of a tender (proposal input v2: buyer research, market study) and its deck runs
const studioTender = async id => {
  const r = await http('GET', `${STUDIO_URL}/api/tenders/${studioId(id)}`);
  if (r.status === 404) return { missing: true };
  if (r.status !== 200 || !r.body) return { error: r.status ? `the proposal studio answered HTTP ${r.status}` : 'the proposal studio is not reachable' };
  return { input: r.body };
};
const runOf = g => g && {
  run_id: g.runId, status: g.status, step: g.step || null, created_at: g.createdAt || null, deck_id: g.deckId || null,
  placeholders: typeof g.placeholders === 'number' ? g.placeholders : null, warnings: Array.isArray(g.warnings) ? g.warnings.length : 0,
  error: cut(g.error, 160) || null, deck_url: g.deckId ? deckLink(g.deckId, g.tenderId) : null, tender_id: g.tenderId || null,
};

// ---------------------------------------------------------------- the tools
const TOOLS = {
  async list_tenders() {
    const st = await tenders();
    if (st.error) return fail(st.error);
    const q = s(inp.query).toLowerCase(), minFit = Number(s(inp.min_fit)) || 0;
    const within = Number(s(inp.deadline_within_days)) || 0, since = Number(s(inp.published_within_days)) || 0;
    const all = s(inp.include_closed) === 'yes';
    let rows = st.list.map(summary);
    const filters = [];
    if (!all) { rows = rows.filter(t => t.days_left == null || t.days_left >= 0); filters.push('open (deadline not passed)'); }
    if (q) { rows = rows.filter(t => `${t.title} ${t.buyer} ${t.tender_id}`.toLowerCase().includes(q)); filters.push(`matching "${cut(q, 40)}"`); }
    if (minFit) { rows = rows.filter(t => (t.fit || 0) >= minFit); filters.push(`fit ${minFit} or more`); }
    if (within) { rows = rows.filter(t => t.days_left != null && t.days_left <= within); filters.push(`deadline within ${within} days`); }
    if (since) { rows = rows.filter(t => t.published && daysBetween(t.published, today) <= since); filters.push(`published in the last ${since} days`); }
    rows.sort((a, b) => (b.fit ?? -1) - (a.fit ?? -1) || (a.days_left ?? 9999) - (b.days_left ?? 9999));
    const limit = Math.min(Math.max(Number(s(inp.limit)) || 5, 1), 10);
    return out({ ok: true, tool, today, total: rows.length, shown: Math.min(limit, rows.length), filters, tenders: rows.slice(0, limit),
      note: rows.some(t => t.demo) ? 'tenders with demo: true are fictional demo tenders: always say "demo"' : undefined });
  },

  async get_tender() {
    const f = await findTender(inp.tender_id);
    if (!f.tender) return notFound(f);
    const t = f.tender, a = t.rag_analysis || {};
    const st = await studioTender(t.tender_id);
    const summ = st.input && st.input.matrix && st.input.matrix.summary;
    return out({ ok: true, tool, today, tender: { ...summary(t),
      fit_detail: a.fit_score || null, gaps: (a.knowledge_gaps || []).length,
      team_size: a.team_proposal && a.team_proposal.size || 0,
      requirements_text: ['technical', 'team', 'experience'].flatMap(k => ((t.requirements || {})[k] || []).map(r => cut(r, 120))).slice(0, 8),
      in_studio: !!st.input, recommendation: summ ? s(summ.recommendation) || null : null,
      recommendation_reason: summ ? cut(summ.recommendation_reason, 200) || null : null } });
  },

  async get_requirements_matrix() {
    const f = await findTender(inp.tender_id);
    if (!f.tender) return notFound(f);
    const m = (f.tender.rag_analysis && f.tender.rag_analysis.requirements_matrix) || [];
    const rows = m.slice(0, 15).map((r, i) => ({ n: i + 1, requirement: cut(r.requirement, 140), category: r.category || null, mandatory: !!r.mandatory,
      status: r.status, basis: s(r.best_doc) || (r.closest_doc ? `closest: ${s(r.closest_doc)}` : null), evidence: cut(r.evidence || r.statement, 140) || null,
      demo_evidence: r.origin === 'demo' }));
    return out({ ok: true, tool, tender: summary(f.tender), total: m.length, rows });
  },

  async get_team() {
    const f = await findTender(inp.tender_id);
    if (!f.tender) return notFound(f);
    const tp = f.tender.rag_analysis && f.tender.rag_analysis.team_proposal;
    const members = (tp && tp.members || []).slice(0, 8).map(p => ({ name: s(p.name) || null, title: cut(p.title, 80), seniority: p.seniority || null,
      years: typeof p.years === 'number' ? p.years : null, roles: (p.roles || []).slice(0, 4), certifications: (p.certifications || []).slice(0, 5).map(c => cut(c, 60)),
      assigned_to: (p.assigned_to || []).slice(0, 4).map(x => cut(x, 80)), cv: p.doc_id || null }));
    return out({ ok: true, tool, tender: summary(f.tender), team_size: tp ? tp.size || members.length : 0, method: tp ? tp.method || null : null, members,
      note: members.length ? undefined : 'the RAG proposed no team for this tender (no team requirement, or no matching CV)' });
  },

  async get_gaps() {
    const f = await findTender(inp.tender_id);
    if (!f.tender) return notFound(f);
    const g = (f.tender.rag_analysis && f.tender.rag_analysis.knowledge_gaps) || [];
    return out({ ok: true, tool, tender: summary(f.tender), total: g.length, gaps: g.slice(0, 10).map(x => ({ requirement: cut(x.requirement, 140), status: x.status || null,
      mandatory: !!x.mandatory, gap: cut(x.gap, 160) || null, suggestion: cut(x.suggestion, 160) || null })) });
  },

  async get_prospect() {
    const f = await findTender(inp.tender_id);
    if (!f.tender) return notFound(f);
    const st = await studioTender(f.tender.tender_id);
    if (st.error) return fail(st.error);
    const b = st.input && st.input.buyer_profile;
    if (!b) return out({ ok: true, tool, tender: summary(f.tender), research_status: 'missing',
      note: 'no buyer research: n8n researches the buyers of fit tenders only (and never the demo buyers)' });
    return out({ ok: true, tool, tender: summary(f.tender), research_status: b.research_status || null, buyer: {
      name: s(b.name) || null, legal_name: s(b.legal_name) || null, sector: s(b.sector) || null, size: s(b.size) || null, staff: s(b.staff) || null,
      revenue: s(b.estimated_revenue) || null, website: s(b.website) || null, description: cut(b.organization_description, 300) || null,
      emails: ((b.contacts && b.contacts.emails) || []).slice(0, 3), phones: ((b.contacts && b.contacts.phones) || []).slice(0, 2),
      past_projects: (b.past_digital_projects || []).slice(0, 5).map(p => ({ title: cut(p.title, 100), date: p.date || null })),
      past_winners: (b.past_winners || []).slice(0, 5).map(w => ({ name: cut(w.name, 60), wins: w.wins ?? null })) } });
  },

  async get_market() {
    const f = await findTender(inp.tender_id);
    if (!f.tender) return notFound(f);
    const st = await studioTender(f.tender.tender_id);
    if (st.error) return fail(st.error);
    const c = st.input && st.input.competition;
    if (!c) return out({ ok: true, tool, tender: summary(f.tender), status: 'NOT_STUDIED', declared_value: summary(f.tender).budget,
      note: 'no market study for this tender (n8n studies the best fit tenders only)' });
    const b = c.budget_estimate || null;
    return out({ ok: true, tool, tender: summary(f.tender), status: s(c.status) || null, declared_value: s(c.declared_value) || null,
      budget_range: b ? { low: b.low ?? null, mid: b.mid ?? null, high: b.high ?? null, currency: b.currency || null, confidence: b.confidence || null,
        comparables: b.comparables ?? null, basis: cut(b.basis, 160) || null } : null,
      competitors: (c.competitors || []).slice(0, 5).map(x => ({ name: cut(x.name, 60), past_wins: x.past_wins ?? null })),
      median_bids: c.median_bids ?? null, positioning: cut(c.positioning, 400) || null,
      note: 'budget figures are computed by code from awarded contracts; OliveSoft prices are set in the studio, never in chat' });
  },

  async search_knowledge() {
    // "Power BI; 2 data engineers; a PMP": one requirement per ';' or new line, in the category the agent chose
    const lines = String(inp.query || '').split(/[;\n]+/).map(x => cut(x, 200)).filter(x => x.length >= 2).slice(0, 6);
    if (!lines.length) return fail('no requirement given: write them in query, separated by ";"');
    const cat = ['technical', 'team', 'experience'].includes(s(inp.category)) ? s(inp.category) : 'technical';
    // team lines ("2 data engineers", "a project manager with PMP") are matched against the CVs; a role word sends a line there
    const isTeam = l => cat === 'team' || /\b(engineers?|developers?|d[ée]veloppeurs?|ing[ée]nieurs?|chefs? de projet|project managers?|consultants?|architects?|architectes?|experts?|analysts?|PMP|scrum|certifi)/i.test(l);
    const body = { technical: [], team: [], experience: [] };
    for (const l of lines) (cat === 'experience' ? body.experience : isTeam(l) ? body.team : body.technical).push(l);
    const r = await http('POST', `${RAG_URL}/retrieve`, body);
    if (r.status !== 200 || !r.body) return fail(r.status ? `the RAG service answered HTTP ${r.status}` : 'the RAG service is not reachable');
    const m = r.body.requirements_matrix || [];
    const tp = r.body.team_proposal;
    return out({ ok: true, tool, rows: m.map((x, i) => ({ n: i + 1, requirement: cut(x.requirement, 140), category: x.category || null, status: x.status,
        found: x.found ?? null, needed: x.needed ?? null, basis: s(x.best_doc) || (x.closest_doc ? `closest: ${s(x.closest_doc)}` : null),
        evidence: cut(x.evidence || x.statement, 160) || null })),
      team: tp ? (tp.members || []).slice(0, 6).map(p => ({ name: s(p.name) || null, title: cut(p.title, 80), certifications: (p.certifications || []).slice(0, 4),
        assigned_to: (p.assigned_to || []).slice(0, 3).map(x => cut(x, 80)) })) : [],
      fit: r.body.fit_score ? r.body.fit_score.overall ?? null : null });
  },

  async deck_status() {
    const ref = cleanRef(inp.tender_id);
    if (!ref) {   // no tender: the latest runs of every tender
      const r = await http('GET', `${STUDIO_URL}/api/generations`);
      if (r.status !== 200 || !r.body) return fail(r.status ? `the proposal studio answered HTTP ${r.status}` : 'the proposal studio is not reachable');
      const runs = (r.body.generations || []).slice(0, 3).map(runOf);
      return out({ ok: true, tool, runs, note: runs.length ? undefined : 'no deck was generated yet' });
    }
    const f = await findTender(ref);
    if (!f.tender) return notFound(f);
    const r = await http('GET', `${STUDIO_URL}/api/generations?tenderId=${encodeURIComponent(studioId(f.tender.tender_id))}`);
    if (r.status !== 200 || !r.body) return fail(r.status ? `the proposal studio answered HTTP ${r.status}` : 'the proposal studio is not reachable');
    const runs = (r.body.generations || []).map(runOf);
    return out({ ok: true, tool, tender: summary(f.tender), last_run: runs[0] || null, runs: runs.length,
      note: runs.length ? undefined : 'no deck for this tender yet: start_deck makes one' });
  },

  async export_deck() {
    // the studio exports from its editor (it renders the slides there) and only after the prices are approved: a link, no file
    const f = await findTender(inp.tender_id);
    if (!f.tender) return notFound(f);
    const r = await http('GET', `${STUDIO_URL}/api/generations?tenderId=${encodeURIComponent(studioId(f.tender.tender_id))}`);
    const done = r.status === 200 && r.body ? (r.body.generations || []).map(runOf).find(g => g.status === 'done' && g.deck_id) : null;
    if (!done) return fail('this tender has no finished deck yet', { tender: summary(f.tender) });
    return out({ ok: true, tool, tender: summary(f.tender), deck_id: done.deck_id, deck_url: done.deck_url, placeholders: done.placeholders,
      note: 'open the deck, approve the prices and fill the [TO FILL] placeholders, then Export PPTX or PDF in the editor (prices are never approved from chat)' });
  },

  async start_deck() {
    if (!canAct) return needAct();
    const f = await findTender(inp.tender_id);
    if (!f.tender) return notFound(f);
    const t = f.tender;
    const r = await http('POST', `${STUDIO_URL}/api/generations`, { tenderId: studioId(t.tender_id), params: {} });
    const said = r.body && typeof r.body.message === 'string' ? cut(r.body.message, 160) : '';
    if (r.status === 202 && r.body && typeof r.body.runId === 'string') {
      return out({ ok: true, tool, tender: summary(t), run_id: r.body.runId, started: true, audit: { action: 'start_deck', tender_id: t.tender_id, run_id: r.body.runId },
        note: 'the deck takes about 2 to 5 minutes; the bot posts it in this conversation when it is ready' });
    }
    const why = { 404: 'this tender is not in the proposal studio (n8n sends the fit, open tenders only)',
      409: 'another deck is being generated (the studio makes one at a time): try again when it is done',
      503: 'deck generation is not configured in the proposal studio', 502: 'the proposal studio cannot reach the deck agents' }[r.status];
    return fail(why || (r.status ? `the proposal studio answered HTTP ${r.status}${said ? `: ${said}` : ''}` : 'the proposal studio is not reachable'), { tender: summary(t) });
  },

  async refine_slide() {
    if (!canAct) return needAct();
    const deckId = cleanRef(inp.deck_id);
    if (!/^[A-Za-z0-9_-]{1,64}$/.test(deckId)) return fail('deck_id is missing or invalid: call deck_status to get it');
    // the slide number the editor shows (1 = the title slide) -> the studio's 0-based index
    const n = Number(s(inp.slide));
    if (!Number.isInteger(n) || n < 1) return fail('slide must be the slide number shown in the editor (1 = the title slide)');
    if (n === 1) return fail('the title slide cannot be refined');
    const instruction = cut(inp.instruction, 200);
    if (instruction.length < 3) return fail('write an instruction of at least 3 characters');
    const r = await http('POST', REFINE_URL, { deckId, slideIndex: n - 1, instruction });
    const b = r.body && typeof r.body === 'object' ? r.body : {};
    if (r.status === 200 && b.status === 'ok') {
      return out({ ok: true, tool, deck_id: deckId, slide: n, title: cut(b.title, 120), warnings: (b.warnings || []).length, deck_url: deckLink(deckId),
        audit: { action: 'refine_slide', deck_id: deckId, slide: n }, note: 'a refined slide with prices needs a new price approval in the studio before export' });
    }
    return fail(cut(b.message, 200) || (r.status ? `Refine Slide answered HTTP ${r.status}` : 'Refine Slide is not reachable (is "RFP - Refine Slide" published?)'));
  },

  async record_no_bid() {
    if (!canAct) return needAct();
    const f = await findTender(inp.tender_id);
    if (!f.tender) return notFound(f);
    const reason = cut(inp.reason, 300);
    if (reason.length < 3) return fail('a no-bid needs a reason of 3 to 300 characters: ask the user why');
    const t = f.tender;
    const r = await http('PUT', `${RAG_URL}/api/tenders/${encodeURIComponent(t.tender_id)}/decision`, { decision: 'no_bid', reason });
    if (r.status !== 200) return fail(r.status ? `the RAG service answered HTTP ${r.status}` : 'the RAG service is not reachable', { tender: summary(t) });
    return out({ ok: true, tool, tender: summary(r.body && r.body.tender_id ? r.body : t), decision: 'no_bid', reason,
      audit: { action: 'record_no_bid', tender_id: t.tender_id } });
  },
};

if (!TOOLS[tool]) return fail(`unknown tool "${cut(tool, 40)}"`);
try {
  return await TOOLS[tool]();
} catch (e) {
  return fail(`the tool failed: ${cut(e.message || e, 160)}`);
}

// ============================================================================
// RFP - Chat: Answer command. A card button or a fixed command ran ONE tool ("Run command", the same code as the agent's
// tools) without any model: its result -> the bot's reply {text, language, cards, audit}, every sentence written here.
// ============================================================================
// ---- shared helpers ----
// the Teams bot's cards (RFP - Chat): built by code from the tools' results, never written by a model. One card per kind (the
// last call wins), at most 2 per answer. Their shapes are rendered by services/teams-bot/bot/cards.py
const chatCards = results => {
  const kinds = new Map();
  for (const d of results) {
    if (!d || d.ok !== true) continue;
    const t = d.tender || {};
    let c = null;
    if (d.tool === 'list_tenders') c = { type: 'tender_list', data: { tenders: d.tenders || [], total: d.total || 0, filters: d.filters || [] } };
    else if (d.tool === 'get_tender' || d.tool === 'record_no_bid') c = { type: 'tender', data: t };
    else if (d.tool === 'get_requirements_matrix') c = { type: 'matrix', data: { tender: t, rows: (d.rows || []).slice(0, 8), total: d.total || 0 } };
    else if (d.tool === 'search_knowledge') c = { type: 'coverage', data: { rows: (d.rows || []).slice(0, 8), team: d.team || [] } };
    else if (d.tool === 'deck_status' && d.last_run) c = { type: 'deck', data: { ...d.last_run, title: t.title || null, tender_id: t.tender_id || d.last_run.tender_id } };
    else if (d.tool === 'deck_status' && Array.isArray(d.runs) && d.runs.length) c = { type: 'deck', data: d.runs[0] };
    else if (d.tool === 'export_deck') c = { type: 'deck', data: { status: 'done', deck_id: d.deck_id, deck_url: d.deck_url, placeholders: d.placeholders, title: t.title, tender_id: t.tender_id } };
    else if (d.tool === 'start_deck') c = { type: 'deck', data: { status: 'running', run_id: d.run_id, title: t.title, tender_id: t.tender_id } };
    if (c) { kinds.delete(c.type); kinds.set(c.type, c); }
  }
  return [...kinds.values()].slice(-2);
};
// ---- end helpers ----
const msg = $('Check message').first().json;
const d = $input.first().json || {};
const fr = msg.language === 'fr';
const L = (en, f) => (fr ? f : en);
const t = d.tender || {};
const name = t.title ? `"${t.title}"${t.demo ? ' (demo)' : ''}` : L('this tender', 'cet appel d\'offres');

let text;
if (!d.ok) {
  text = d.not_allowed ? L('Only the approvers can run this action. Ask one of them, or ask me a question instead.',
    'Seuls les approbateurs peuvent lancer cette action. Demandez à l\'un d\'eux, ou posez-moi une question.')
    : L(`It did not work: ${d.error || 'unknown error'}.`, `Cela n'a pas fonctionné : ${d.error || 'erreur inconnue'}.`);
} else if (d.tool === 'list_tenders') {
  text = d.total ? L(`${d.total} open tender${d.total > 1 ? 's' : ''}, the ${d.shown} best by fit:`, `${d.total} appel${d.total > 1 ? 's' : ''} d'offres ouvert${d.total > 1 ? 's' : ''}, les ${d.shown} meilleurs par adéquation :`)
    : L('No open tender in the store. Run "RFP - Main" in n8n to find new ones.', 'Aucun appel d\'offres ouvert. Lancez « RFP - Main » dans n8n pour en trouver.');
} else if (d.tool === 'start_deck') {
  text = L(`Generating the deck for ${name} (run ${d.run_id}). It takes 2 to 5 minutes: I will post it here when it is ready.`,
    `Génération de la présentation pour ${name} (run ${d.run_id}). Cela prend 2 à 5 minutes : je la publierai ici dès qu'elle sera prête.`);
} else if (d.tool === 'record_no_bid') {
  text = L(`No-bid recorded for ${name}. Reason: ${d.reason}`, `No-bid enregistré pour ${name}. Raison : ${d.reason}`);
} else if (d.tool === 'deck_status') {
  const run = d.last_run || (Array.isArray(d.runs) ? d.runs[0] : null);
  text = run ? L('The latest deck run:', 'La dernière génération :') : L('No deck has been generated yet.', 'Aucune présentation n\'a encore été générée.');
} else if (d.tool === 'get_requirements_matrix') {
  text = L(`Requirements matrix of ${name} (${d.total} requirements):`, `Matrice des exigences de ${name} (${d.total} exigences) :`);
} else {
  text = L(`Here is ${name}:`, `Voici ${name} :`);
}

const audit = d.ok && d.audit ? [d.audit] : [];
return [{ json: {
  reply: { text, language: msg.language, cards: chatCards([d]), audit },
  watch: d.tool === 'start_deck' && d.ok && d.run_id ? { run_id: d.run_id, tender_id: t.tender_id, title: t.title } : null,
} }];

// ============================================================================
// RFP - Chat: Watch deck. Runs AFTER Respond (the user already has "Generating..."): polls the studio's run of the deck that
// start_deck started (GET /api/generations/<runId>) every 15 s for up to 12 minutes, then gives "Notify Teams" the card to
// post in the same conversation: the deck link, slide placeholders and warnings, or the failure. Never longer than n8n's task
// timeout (N8N_RUNNERS_TASK_TIMEOUT, 1200 s in docker-compose.yml).
// ============================================================================
const STUDIO_URL = 'http://host.docker.internal:8091';      // patched by n8n/init/init.js
const WEB_APP_URL = 'http://localhost:5173';                 // patched by n8n/init/init.js (TEAMS_WEB_APP_URL)
const BOT_NOTIFY_URL = 'http://host.docker.internal:3978/notify';   // patched by n8n/init/init.js (the teams-bot service)
const EVERY_MS = 15000, MAX_MS = 12 * 60 * 1000;

const msg = $('Check message').first().json;
const w = $input.first().json.watch || {};
const fr = msg.language === 'fr';
const L = (en, f) => (fr ? f : en);
const sleep = ms => new Promise(res => setTimeout(res, ms));
const deckLink = (deckId, tenderId) => `${WEB_APP_URL}/decks/${encodeURIComponent(deckId)}${tenderId ? `?tender=${encodeURIComponent(tenderId)}` : ''}`;

let run = null, misses = 0;
const start = Date.now();
while (Date.now() - start < MAX_MS) {
  await sleep(EVERY_MS);
  try {
    run = await this.helpers.httpRequest({ method: 'GET', url: `${STUDIO_URL}/api/generations/${w.run_id}`, json: true, timeout: 15000 });
    misses = 0;
  } catch (e) {
    if (++misses >= 8) break;                      // the studio stopped answering for 2 minutes
    continue;
  }
  if (run && (run.status === 'done' || run.status === 'failed')) break;
}

const name = w.title ? `"${w.title}"` : L('the tender', 'l\'appel d\'offres');
let text, data;
if (run && run.status === 'done' && run.deckId) {
  const placeholders = typeof run.placeholders === 'number' ? run.placeholders : null;
  data = { status: 'done', run_id: w.run_id, deck_id: run.deckId, deck_url: deckLink(run.deckId, w.tender_id), tender_id: w.tender_id, title: w.title,
    placeholders, warnings: Array.isArray(run.warnings) ? run.warnings.length : 0, slides: Array.isArray(run.slides) ? run.slides.length : null };
  text = L(`The deck for ${name} is ready.`, `La présentation pour ${name} est prête.`) + (placeholders
    ? L(` ${placeholders} [TO FILL] placeholder${placeholders > 1 ? 's' : ''} to fill and the prices to approve before export.`,
      ` ${placeholders} élément${placeholders > 1 ? 's' : ''} [TO FILL] à compléter et les prix à approuver avant l'export.`)
    : L(' Approve the prices in the editor before export.', ' Approuvez les prix dans l\'éditeur avant l\'export.'));
} else if (run && run.status === 'failed') {
  data = { status: 'failed', run_id: w.run_id, tender_id: w.tender_id, title: w.title, error: String(run.error || '').slice(0, 200) || null };
  text = L(`The deck for ${name} failed. Open the tender in the app to retry.`, `La génération pour ${name} a échoué. Ouvrez l'appel d'offres dans l'application pour réessayer.`);
} else {
  data = { status: run ? run.status : 'unknown', run_id: w.run_id, tender_id: w.tender_id, title: w.title };
  text = L(`The deck for ${name} is still not finished after 12 minutes. Type "status" later.`, `La présentation pour ${name} n'est toujours pas prête après 12 minutes. Tapez « statut » plus tard.`);
}
return [{ json: { notifyUrl: BOT_NOTIFY_URL, body: { conversation_id: msg.conversation_id, kind: 'deck', text, language: msg.language, cards: [{ type: 'deck', data }] } } }];
